window.CYP_PLANT_DETAILS={"shard":"liquidambar-styraciflua-7c9dddbe","records":[{"detailId":"00005070","cypName":"CYP84A3","id":"CYP84A3","recordKey":"bibliod:block-3554:line-20835:cyp84a3","category":"plants","species":"Liquidambar styraciflua","description":"biblioD.html historical bibliography block 3554 at source line 20835; source species text=Liquidambar styraciflua (sweetgum); CYP84A3 Liquidambar styraciflua (sweetgum) / GenEMBL AF139532 / Osakabe,K., Tsao,C.C., Li,L., Popko,J.L., Umezawa,T., / Carraway,D.T., Smeltzer,R.H., Joshi,C.P. and Chiang,V.L. / Coniferyl aldehyde 5-hydroxylation and methylation direct syringyl / lignin biosynthesis in angiosperms / Proc. Natl. Acad. Sci. U.S.A. 96, 8955-8960 (1999) / 75% identical to CYP84A1 / Note: This paper shows coniferyl aldehyde 5-hydroxylation as the primary / function of the CYP84A P450s and not ferulate-5-hydroxylation. When both / coniferyl aldehyde and ferulate are present, coniferyl aldehyde is a noncompetitive / inhibitor of ferulate-5-hydroxylation and shuts down this potential pathway.","sequence":"","phgoLite":"\u003eLiquidambar_styraciflua|CYP84A3(CYP84A3)","sourceUrl":"https://drnelson.uthsc.edu/wp-content/uploads/sites/130/resources/biblioD.html"}]};
